const HydraBodyDefinition &HydraBody::rule(const RunRuntime &r,const BossBodyState &b) {const auto id=r.content->boss_bodies[b.definition-1].boss;return *std::find_if(r.content->hydra_bodies.begin(),r.content->hydra_bodies.end(),[&](const auto &p){return p.boss==id;});}
EnemyHandle HydraBody::spawn(RunRuntime &r,uint32_t definition,godot::Vector2 at,bool entrance) {if (!definition || definition>r.content->boss_bodies.size() || r.content->bosses[r.content->boss_bodies[definition-1].boss-1].kind!=3) return {};return PhaseController::spawn(r,definition,at,entrance);}
void HydraBody::spawned(RunRuntime &r,BossBodyState &b) {
    auto &s=r.state;const auto &p=rule(r,b);const auto at=s.enemies[b.actor.slot].pos;const auto center=(at+s.ship_pos)*0.5;const auto size=godot::Vector2(p.arena_x,p.arena_y).max((at-s.ship_pos).abs()+godot::Vector2(900,900));const godot::Rect2 bounds(center-size*0.5,size);s.field.arenas.push_back({b.actor,bounds});
    const auto clear=[&](godot::Vector2 point,double radius){return bounds.grow(p.arena_wall_thickness+80+radius).has_point(point)?FieldSystem::safe_point(r,bounds,point,radius+12):point;};
    for (auto &e:s.enemies) {e.body_gap=-1;if (e.alive && !e.dead && e.id!=s.enemy_handles.entity_id(b.actor)) {const auto next=clear(e.pos,e.radius);if (next!=e.pos) {e.pos=next;e.vel={};}}}
    for (auto &shot:s.hostiles) shot.gap=0;
    for (auto &rock:s.field.rocks) if (!rock.destroyed) {const auto pos=FieldSystem::rock_at(r,rock),next=clear(pos,rock.size);if (next!=pos) {rock.position=next;rock.velocity={};}}
    for (auto &v:s.pickups.gems) if (v.alive) {const auto next=clear(v.pos,12);if (next!=v.pos) {v.pos=next;v.velocity={};}}
    for (auto &v:s.pickups.coins) if (v.alive) v.pos=clear(v.pos,12);for (auto &v:s.pickups.capsules) v.pos=clear(v.pos,24);
    for (uint32_t k=0;k<3;++k) {HydraNeckState n;n.kind=HydraHeadKind(k);n.base_angle=tau*k/3.0;n.angle=n.base_angle+s.enemies[b.actor.slot].facing;n.length=p.neck_rest*0.3;n.cd=p.attack_cd*(0.5+0.5*s.control.rng.randf());const auto definition=k==0?p.bite:k==1?p.vortex:p.debris;const auto id=EnemySystem::spawn_part(r,b.actor,definition-1,head(r,b,n));if (id<0) continue;n.actor=s.enemy_handles.at(s.rows_by_id.at(id));n.id=id;auto &e=s.enemies[n.actor.slot];e.hp=e.max_hp=p.head_hp*r.content->definitions[r.content->boss_bodies[b.definition-1].enemy-1].scaling.hp_mult;n.head_hp=e.hp;b.participants.push_back({n.actor,n.actor,id,false,true});chain(r,b,n,0);b.hydra.necks.push_back(n);}
}
void HydraBody::step(RunRuntime &r,BossBodyState &b,double dt) {
    const auto &p=rule(r,b);auto &e=r.state.enemies[b.actor.slot];const auto &d=r.content->bosses[r.content->boss_bodies[b.definition-1].boss-1];const TrackingPolicy tracking{r.state.draw.tracing,e.held,r.state.enemy_handles.contains(e.pump_owner)};const auto delta=r.state.ship_pos-e.pos;const double distance=std::max(1.0,double(delta.length()));const bool swim=distance>p.engage || !godot::Rect2(r.state.view_center-r.state.view_half,r.state.view_half*2).grow(-e.radius).has_point(e.pos);bool resting=false;for (const auto &flow:r.state.bosses.flows) if (same_handle(flow.actor,b.actor) && flow.rest_remaining>0) resting=true;
    if (!resting) {const auto want=swim?tracking.velocity(e.vel,e.facing,delta/distance*d.speed):godot::Vector2();e.vel+=(want-e.vel)*std::min(1.0,p.accel*dt);if (swim && !tracking.locked()) e.facing+=std::clamp(angle_difference(delta.angle()-e.facing),-d.turn*dt,d.turn*dt);const auto from=e.pos;e.pos+=e.vel*dt;FieldSystem::collide_enemy(r,b.actor.slot,from,dt);for (const auto &a:r.state.field.arenas) if (same_handle(a.owner,b.actor)) {const auto rect=a.bounds.grow(-e.radius-p.neck_rest-80);e.pos=e.pos.clamp(rect.position,rect.get_end());}} else e.vel={};
    for (auto &n:b.hydra.necks) {if (r.state.enemy_handles.contains(n.actor) && !r.state.enemies[n.actor.slot].dead) {n.cd=std::max(0.0,n.cd-dt);n.aim_wait=std::max(0.0,n.aim_wait-dt);if (!n.has_aim || n.aim_wait<=0) {n.has_aim=true;n.aim_target=r.state.ship_pos;n.aim_wait=p.aim_refresh;}const double facing=n.base_angle+e.facing;const auto offset=n.aim_target-base(r,b,n),forward=godot::Vector2::from_angle(facing);const double local=std::atan2(offset.dot(forward.orthogonal()),std::max(p.aim_deadzone,double(offset.dot(forward)))),desired=facing+std::clamp(local,-0.8,0.8)+std::sin(b.clock+n.base_angle)*0.06;if (!tracking.locked()) {const double diff=angle_difference(desired-n.angle),speed=std::min(p.aim_turn,std::sqrt(2*p.aim_accel*std::abs(diff))),velocity=toward(n.aim_velocity,(diff>0?1:diff<0?-1:0)*speed,p.aim_accel*dt);double move=velocity*dt;if (move*diff>=0 && std::abs(move)>std::abs(diff)) move=diff;n.angle+=move;n.aim_velocity=move/dt;}n.length=toward(n.length,p.neck_rest,p.neck_rest*dt);auto &part=r.state.enemies[n.actor.slot];part.pos=head(r,b,n);part.facing=n.angle;part.vel={};n.head_hp=part.hp;}else n.length=std::max(0.0,n.length-p.neck_rest*dt);chain(r,b,n,dt);}
}
void HydraBody::part_defeated(RunRuntime &r,const DeathContext &death) {for (auto &b:r.state.bosses.bodies) for (auto &n:b.hydra.necks) if (same_handle(n.actor,death.target)) {for (auto &p:b.participants) if (same_handle(p.actor,n.actor)) p.active=false;n.actor={};return;}}
void HydraBody::release(RunRuntime &r,BossBodyState &b) {auto &arenas=r.state.field.arenas;arenas.erase(std::remove_if(arenas.begin(),arenas.end(),[&](const auto &a){return same_handle(a.owner,b.actor);}),arenas.end());for (auto &n:b.hydra.necks) if (r.state.enemy_handles.contains(n.actor) && !r.state.enemies[n.actor.slot].dead) EnemySystem::retire(r,n.actor,RetireReason::Development);}
bool HydraBody::owns_part(const RunRuntime &r,EnemyHandle actor) {for (const auto &b:r.state.bosses.bodies) for (const auto &n:b.hydra.necks) if (same_handle(n.actor,actor)) return true;return false;}
bool HydraBody::validate(const godot::RunState &s,const ContentBundle &c,const BossBodyState &b) {if (c.bosses[c.boss_bodies[b.definition-1].boss-1].kind!=3) return true;if (b.hydra.necks.size()!=3 || b.participants.size()!=4) return false;const bool active=b.mode<BossMode::Defeated;size_t arenas=0;for (const auto &a:s.field.arenas) if (same_handle(a.owner,b.actor)) ++arenas;if (arenas!=size_t(active)) return false;for (size_t i=0;i<b.hydra.necks.size();++i) {const auto &n=b.hydra.necks[i];const auto &part=b.participants[i+1];if (n.kind>=HydraHeadKind::Count || n.id<=0 || n.id!=part.id || part.is_body || !same_handle(part.actor,part.health_target) || !n.aim_target.is_finite()) return false;if (active && part.active && (!s.enemy_handles.contains(n.actor) || s.enemies[n.actor.slot].dead || !same_handle(n.actor,part.actor) || !same_handle(s.enemies[n.actor.slot].parent,b.actor))) return false;for (double v:{n.base_angle,n.angle,n.length,n.head_hp,n.cd,n.aim_wait,n.aim_velocity}) if (!std::isfinite(v)) return false;for (const auto point:n.points) if (!point.is_finite()) return false;}return true;}
void HydraBody::snapshot(const RunRuntime &r,const BossBodyState &b,godot::Dictionary &out) {out["separation_pending"]=b.hydra.separation_pending;out["separated"]=false;out["count"]=uint32_t(b.hydra.necks.size());for (const auto &a:r.state.field.arenas) if (same_handle(a.owner,b.actor)) out["arena"]=a.bounds;out["arena_wall_thickness"]=rule(r,b).arena_wall_thickness;godot::Array necks;for (const auto &n:b.hydra.necks) {godot::Dictionary v;v["id"]=n.id;v["kind"]=symbol_name(n.kind);v["angle"]=n.angle;v["facing"]=r.state.enemy_handles.contains(n.actor)?r.state.enemies[n.actor.slot].facing:n.angle;v["hp"]=r.state.enemy_handles.contains(n.actor)?r.state.enemies[n.actor.slot].hp:0;v["max_hp"]=r.state.enemy_handles.contains(n.actor)?r.state.enemies[n.actor.slot].max_hp:0;v["length"]=n.length;v["head_hp"]=n.head_hp;v["alive"]=r.state.enemy_handles.contains(n.actor) && !r.state.enemies[n.actor.slot].dead;v["position"]=head(r,b,n);v["radius"]=r.state.enemy_handles.contains(n.actor)?r.state.enemies[n.actor.slot].radius:40;godot::PackedVector2Array points;for (const auto point:n.points) points.push_back(point);v["points"]=points;necks.push_back(v);}out["necks"]=necks;}
